    repeat (split; [eassumption|]); eassumption.

  Section STREAM3.
  Variables (k SE OPk DBC : Z) (ws : list word).
  Hypothesis K4 : 0 <= k < 4.
  Hypothesis HSE : DST <= OPk <= SE.
  Hypothesis HSE2 : SE <= DST + dcap.
  Hypothesis WOP : nth_error ws (Z.to_nat (4 + k)) = Some (Z_to_bv 64 OPk).

  Notation ST pc mm x9 a1 a2 a3 x18 x19 x20 x24 x25 x26 x27 :=
    (MS (mkR (Z_to_bv 64 (SP + -192)) (Z_to_bv 64 (SP + -416)) gp tp (Z_to_bv 64 8) (Z_to_bv 64 k) (Z_to_bv 64 seg)
             (Z_to_bv 64 (SP + -224 + 8 * k)) x9 (Z_to_bv 64 (DT + 4)) a1 a2 a3 (Z_to_bv 64 0x104d0)
             (Z_to_bv 64 (SP + -136)) (Z_to_bv 64 (SP + -256)) (Z_to_bv 64 DBC) x18 x19 x20 (Z_to_bv 64 OPk)
