        F (Z_to_bv 64 pc) fc None mm (seg_rom psegs)).

  Hypothesis CONT : forall mm (x9 a2 a3 x18 x19 x20 x24 x25 x26 x27 : word),
    Y4M mm SPS (upd ws (Z.to_nat (4 + k)) (Z_to_bv 64 SE)) ->
    evt psegs POST (ST 0x15f18 mm x9 (Z_to_bv 64 SE) a2 a3 x18 x19 x20 x24 x25 x26 x27).

  Notation YS l := (YF l k SE OPk DBC ws K4 HSE HSE2 WOP CONT) (only parsing).

  (* [comment removed for export] *)
  Ltac y4cell v :=
    lazymatch goal with |- context [Z.land (((bv_unsigned ?c ≪ ?b) mod 18446744073709551616) ≫ 51) 18446744073709551612] =>
      rewrite (y4_land_m4_shr ((bv_unsigned c ≪ b) mod 18446744073709551616)) by (apply Z.mod_pos_bound; lia);
      let EV := fresh "EV" in let VR := fresh "VR" in
      pose proof (y4_shr53_bound ((bv_unsigned c ≪ b) mod 18446744073709551616) ltac:(apply Z.mod_pos_bound; lia)) as VR;
      remember (((bv_unsigned c ≪ b) mod 18446744073709551616) ≫ 53) as v eqn:EV; clear EV end.
  Ltac y4c v c EC :=
    lazymatch goal with TCK : forall i, 0 <= i < 2^11 -> _, VR : 0 <= v < 2048 |- _ =>
      remember (nth (Z.to_nat v) cells x2_default) as c eqn:EC;
      let SQ := fresh "SQ" in let NB := fresh "NB" in let LN := fresh "LN" in
